ThemeBuilder = {
    init(app, container, theme) {
        app = app || session.app;
        container = container || $(".component[name=ThemeBuilder]");
        if(!theme) { return; }

        if(!theme.colours.charts) {
            theme.colours.charts = [
                "#000000",
                "#000000",
                "#000000",
                "#000000",
                "#000000",
                "#000000"
            ];
        }

        if(!theme.cultureFlagLayout) {
            theme.cultureFlagLayout = "text";
        }

        var model = new kendo.observable(theme);
        kendo.bind(container, model);
        $(container).data("model", model);
        Colours.init(app, $(".component[name=Colours]", container), model);
        Font.init(app, $(".component[name=Font]", container), model);
        Border.init(app, $(".component[name=Border]", container), model);
        Notifications.init(app, $(".component[name=Notifications]", container));
        Shadows.init(app, $(".component[name=Shadows]", container), model);
        Etc.init(app, $(".component[name=Etc]", container));
        $(".partsList > ul > li", container).on("click", function(e) {
            e.preventDefault();
            $(".partsList > ul > li", container).removeClass("selected");
            $(".container", container).css("display", "none");
            $(".container[name=" + $(e.target).attr("data-container") + "]").css("display", "inline-block");
            $(e.target).addClass("selected");
        });
    },

    build(container) {
        return $(container).data("model").toJSON();
    }
}
